<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {http} from '@/api/http'
import type {EChartsOption} from 'echarts'
import {recommendationsApi,type MeasureCatalog} from '@/api/recommendations';import {simulationApi} from '@/api/simulation';import {useSiteStore} from '@/stores/site'
import PageHeader from '@/components/PageHeader.vue';import BaseChart from '@/components/BaseChart.vue';import LoadingState from '@/components/LoadingState.vue';import EmptyState from '@/components/EmptyState.vue';import ErrorState from '@/components/ErrorState.vue';import StatusTag from '@/components/StatusTag.vue'
import type {LoadStatistics,MeasureType,RecommendationConversionRequest,RecommendationPath,RecommendationProfile,RecommendationRun,RecommendationWeights,Scenario,WeatherSite,WeatherStatisticsSummary} from '@/types'

interface Candidate{type:MeasureType;enabled:boolean;capex:number|null;parameters:string}
const route=useRoute(),router=useRouter(),siteStore=useSiteStore();const loading=ref(true),generating=ref(false),error=ref<string|null>(null),failure=ref<string|null>(null),confirmVisible=ref(false),advanced=ref(false),topN=ref(3)
const history=ref<RecommendationRun[]>([]),run=ref<RecommendationRun|null>(null),historyId=ref<number|null>(null),selectedPath=ref<RecommendationPath|null>(null),expanded=ref<number[]>([]),profiles=ref<RecommendationProfile[]>(['ECONOMIC','REDUCTION','BALANCED'])
const simulationYear=ref(new Date().getFullYear()),targetPeak=ref<number|null>(2030),targetNeutral=ref<number|null>(2060),quota=ref<number|null>(null),energyTarget=ref<number|null>(null),budget=ref(500000)
const loadStats=ref<LoadStatistics|null>(null),weatherStats=ref<WeatherStatisticsSummary|null>(null),weatherSites=ref<WeatherSite[]>([]),averageWind=ref<number|null>(null)
const measureCatalog=ref<MeasureCatalog|null>(null),experimentScale=ref<'LOW'|'MEDIUM'|'HIGH'>('MEDIUM')
const profileLabels:Record<RecommendationProfile,string>={ECONOMIC:'经济优先',REDUCTION:'减排优先',BALANCED:'综合平衡'}
const weights=reactive<Record<RecommendationProfile,RecommendationWeights>>({ECONOMIC:{reduction:.2,investment:.2,payback:.2,applicability:.2,target:.2},REDUCTION:{reduction:.2,investment:.2,payback:.2,applicability:.2,target:.2},BALANCED:{reduction:.2,investment:.2,payback:.2,applicability:.2,target:.2}})
const candidates=reactive<Candidate[]>(['PV','WIND','STORAGE','HVAC','LIGHTING','EV_CHARGER','GREEN_POWER'].map(type=>({type:type as MeasureType,enabled:true,capex:null,parameters:'{}'})))
const convertVisible=ref(false),convertPath=ref<RecommendationPath|null>(null),converted=reactive<Record<number,Scenario>>({}),convertForm=reactive<RecommendationConversionRequest>({name:'',description:'',base_year:simulationYear.value,start_year:simulationYear.value,end_year:2060,target_peak_year:targetPeak.value,target_neutral_year:targetNeutral.value})
const site=computed(()=>siteStore.currentSite),enterpriseBase=computed(()=>site.value?{area:site.value.area_m2,population:site.value.population}:null)
const displayedPaths=computed(()=>run.value?.recommendations.filter(x=>profiles.value.includes(x.profile)).sort((a,b)=>a.profile.localeCompare(b.profile)||a.rank-b.rank)||[])
const grouped=computed(()=>Object.fromEntries(profiles.value.map(p=>[p,displayedPaths.value.filter(x=>x.profile===p)])) as Record<RecommendationProfile,RecommendationPath[]>)
const weightTotals=computed(()=>Object.fromEntries(Object.entries(weights).map(([k,v])=>[k,Object.values(v).reduce((a,b)=>a+b,0)])) as Record<RecommendationProfile,number>)
const candidateErrors=computed(()=>candidates.flatMap(x=>{if(!x.enabled)return[];try{const parsed=JSON.parse(x.parameters) as unknown;return parsed!==null&&!Array.isArray(parsed)&&typeof parsed==='object'?[]:[`${x.type} 参数必须为 JSON 对象`]}catch{return[`${x.type} 参数不是有效 JSON`]}}))
const formErrors=computed(()=>{const e=[...candidateErrors.value];if(!profiles.value.length)e.push('至少选择一种推荐画像');if(budget.value<=0)e.push('投资预算必须大于 0');if(topN.value<1||topN.value>10)e.push('Top-N 必须为 1~10');if(advanced.value)for(const p of profiles.value){if(Object.values(weights[p]).some(x=>x<0))e.push(`${profileLabels[p]}权重不能为负`);if(weightTotals.value[p]<=0)e.push(`${profileLabels[p]}权重总和必须大于 0`)}return e})
const requestPreview=computed(()=>({enterprise_id:site.value?.enterprise_id,simulation_year:simulationYear.value,target_peak_year:targetPeak.value,target_neutral_year:targetNeutral.value,carbon_quota_t:quota.value,energy_target_kwh:energyTarget.value,budget:budget.value,top_n:topN.value,profiles:profiles.value,candidates:candidates.filter(x=>x.enabled).map(x=>x.type)}))
const dimensions=(path:RecommendationPath)=>path.metrics_json.score_dimensions
const radarOption=computed<EChartsOption>(()=>{const d=selectedPath.value&&dimensions(selectedPath.value);return {radar:{indicator:[{name:'减排潜力',max:1},{name:'投资成本',max:1},{name:'回收期',max:1},{name:'技术适用性',max:1},{name:'目标满足度',max:1}]},series:[{name:'五维评分',type:'radar',data:d?[{name:`#${selectedPath.value?.rank}`,value:[d.reduction,d.investment,d.payback,d.applicability,d.target]}]:[]}]}})
function comparisonOption(key:'estimated_reduction_t'|'investment'|'payback_years',name:string):EChartsOption{return {grid:{left:65,right:20,top:45,bottom:70},xAxis:{type:'category',axisLabel:{rotate:25},data:displayedPaths.value.map(x=>`${profileLabels[x.profile]} #${x.rank}`)},yAxis:{type:'value'},series:[{name,type:'bar',data:displayedPaths.value.map(x=>x.metrics_json[key]??null)}]}}
const reductionOption=computed(()=>comparisonOption('estimated_reduction_t','减排量 tCO₂')),investmentOption=computed(()=>comparisonOption('investment','投资额')),paybackOption=computed(()=>comparisonOption('payback_years','回收期 年'))
const scatterOption=computed<EChartsOption>(()=>({xAxis:{name:'投资额'},yAxis:{name:'减排量 tCO₂'},series:[{name:'路径',type:'scatter',symbolSize:13,data:displayedPaths.value.filter(x=>x.metrics_json.investment!==undefined&&x.metrics_json.estimated_reduction_t!==undefined).map(x=>[x.metrics_json.investment!,x.metrics_json.estimated_reduction_t!])}]}))
const number=(v:number|undefined|null)=>v===undefined||v===null?'暂无数据':v.toLocaleString('zh-CN',{maximumFractionDigits:4})
const percent=(v:number|undefined)=>v===undefined?'暂无数据':`${(v*100).toFixed(1)}%`
function status(path:RecommendationPath,type:'peak'|'neutral'|'quota'|'energy'|'budget'){const m=path.metrics_json,input=run.value?.input_snapshot_json;if(type==='peak'||type==='neutral')return '无法判断';if(type==='quota')return input?.carbon_quota_t==null?'无法判断':m.carbon_emission_t===undefined?'无法判断':m.carbon_emission_t<=input.carbon_quota_t?'满足':'未满足';if(type==='energy')return input?.energy_target_kwh==null?'无法判断':m.grid_power_kwh===undefined?'无法判断':m.grid_power_kwh<=input.energy_target_kwh?'满足':'未满足';return m.investment===undefined||!input?'无法判断':m.investment<=input.budget?'满足':'未满足'}
function statusType(value:string){return value==='满足'?'success':value==='未满足'?'danger':'info'}

function applyCatalog(){if(!measureCatalog.value||site.value?.code!=='BDG2-RAT')return;for(const candidate of candidates){const item=measureCatalog.value.measures.find(x=>x.measure_code===candidate.type);if(!item)continue;candidate.enabled=item.enabled;candidate.parameters=JSON.stringify(item.experiment_parameters[experimentScale.value],null,2)}}
const catalogItem=(code:MeasureType)=>measureCatalog.value?.measures.find(x=>x.measure_code===code)
async function initialize(){loading.value=true;error.value=null;try{measureCatalog.value=await recommendationsApi.catalog();await siteStore.loadSites();const requested=Number(route.query.site);if(requested){const s=siteStore.sites.find(x=>x.id===requested);if(s)siteStore.selectSite(s)}applyCatalog();await loadContext()}catch(e){error.value=(e as {message?:string}).message||'推荐页面加载失败'}finally{loading.value=false}}
async function loadContext(){if(!site.value){history.value=[];return}history.value=await recommendationsApi.list(site.value.enterprise_id);const requested=Number(route.query.run),selected=history.value.find(x=>x.id===requested)||history.value[0];historyId.value=selected?.id||null;if(selected){run.value=selected;selectedPath.value=run.value.recommendations[0]||null}await loadBaseState()}
async function loadBaseState(){if(!site.value)return;if(site.value.code==='HBUE'){const data=await http.get(`/api/result-interface/campuses/${site.value.id}/simulation-baseline`,{params:{year:simulationYear.value}}) as unknown as {load:LoadStatistics;weather:WeatherStatisticsSummary};loadStats.value=data.load;weatherStats.value=data.weather;weatherSites.value=[];averageWind.value=null;return;}const start=`${simulationYear.value}-01-01T00:00:00`,end=`${simulationYear.value+1}-01-01T00:00:00`;weatherSites.value=await simulationApi.weatherSites(site.value.enterprise_id);loadStats.value=await recommendationsApi.loadStatistics(site.value.enterprise_id,start,end,site.value.timezone).catch(()=>null);const ws=weatherSites.value[0];if(ws){weatherStats.value=await recommendationsApi.weatherStatistics(ws.id,start,end,site.value.timezone).catch(()=>null);const hourly=await recommendationsApi.weatherHourly(ws.id,start,end,site.value.timezone).catch(()=>null),winds=hourly?.items.map(x=>x.wind_speed_m_s).filter((x):x is number=>x!==null&&x!==undefined)||[];averageWind.value=winds.length?winds.reduce((a,b)=>a+b,0)/winds.length:null}else{weatherStats.value=null;averageWind.value=null}}
async function loadHistory(){if(!historyId.value)return;loading.value=true;try{run.value=await recommendationsApi.get(historyId.value);selectedPath.value=run.value.recommendations[0]||null}catch(e){error.value=(e as {message?:string}).message||'历史推荐加载失败'}finally{loading.value=false}}
function buildRequest(){const candidate_parameters:Record<string,{parameters?:Record<string,unknown>;capex?:number;disabled?:boolean}>={};for(const c of candidates){const parameters=c.enabled?JSON.parse(c.parameters) as Record<string,unknown>:{};candidate_parameters[c.type]={parameters,capex:c.enabled?(c.capex??undefined):budget.value+1,disabled:!c.enabled}}return {site_id:site.value!.id,enterprise_id:site.value!.enterprise_id,simulation_year:simulationYear.value,target_peak_year:targetPeak.value,target_neutral_year:targetNeutral.value,carbon_quota_t:quota.value,energy_target_kwh:energyTarget.value,budget:budget.value,top_n:topN.value,weights:advanced.value?Object.fromEntries(profiles.value.map(x=>[x,weights[x]])):{},candidate_parameters}}
async function generate(){confirmVisible.value=false;failure.value=null;generating.value=true;try{run.value=await recommendationsApi.create(buildRequest());history.value=[run.value,...history.value];historyId.value=run.value.id;selectedPath.value=displayedPaths.value[0]||null;expanded.value=[]}catch(e){failure.value=(e as {message?:string}).message||'推荐生成失败'}finally{generating.value=false}}
function openConvert(path:RecommendationPath){convertPath.value=path;convertForm.name=`${profileLabels[path.profile]}推荐路径 #${path.rank}`;convertForm.base_year=simulationYear.value;convertForm.start_year=simulationYear.value;convertForm.end_year=targetNeutral.value||simulationYear.value+20;convertForm.target_peak_year=targetPeak.value;convertForm.target_neutral_year=targetNeutral.value;convertVisible.value=true}
async function convert(){if(!convertPath.value)return;try{const scenario=await recommendationsApi.convert(convertPath.value.id,convertForm);converted[convertPath.value.id]=scenario;convertVisible.value=false}catch(e){failure.value=(e as {message?:string}).message||'转换场景失败'}}
onMounted(initialize)
</script>

<template><section><PageHeader kicker="LOW-CARBON PATHS" title="低碳路径推荐" description="由现有推荐引擎完成候选组合、五维评分和小时仿真验证，前端仅传递目标与约束。"><el-button :loading="loading" @click="initialize"><el-icon><Refresh/></el-icon>刷新</el-button></PageHeader>
<LoadingState v-if="loading"/><ErrorState v-else-if="error" :message="error" @retry="initialize"/><template v-else-if="site">
<el-steps :active="run?4:1" simple class="recommendation-steps"><el-step title="目标配置"/><el-step title="推荐参数"/><el-step title="生成推荐"/><el-step title="三类方案"/><el-step title="转场景/仿真"/></el-steps>
<div class="recommendation-layout"><main>
<article class="panel recommendation-section"><div class="panel-head"><div><span>TARGETS</span><h2>目标配置</h2></div><el-tag>{{site.name}}</el-tag></div><div class="target-grid"><label>Site<el-select :model-value="site.id" @change="(id:number)=>{siteStore.selectSite(siteStore.sites.find(x=>x.id===id)||null);router.replace({query:{site:id}});loadContext()}"><el-option v-for="s in siteStore.sites" :key="s.id" :label="s.name" :value="s.id"/></el-select></label><label>推荐年份<el-input-number v-model="simulationYear"/></label><label>碳达峰目标年份<el-input-number v-model="targetPeak" clearable/></label><label>碳中和目标年份<el-input-number v-model="targetNeutral" clearable/></label><label>碳配额 tCO₂<el-input-number v-model="quota" :min="0" clearable/></label><label>综合能耗目标 kWh<el-input-number v-model="energyTarget" :min="0" clearable/></label><label>投资预算<el-input-number v-model="budget" :min="1"/></label><label>Top-N<el-input-number v-model="topN" :min="1" :max="10"/></label></div></article>

<article class="panel recommendation-section"><div class="panel-head"><div><span>BASELINE CONTEXT</span><h2>基础状态</h2></div><el-button link @click="loadBaseState">重新检查</el-button></div><div class="baseline-grid"><div><span>建筑面积</span><strong>{{site.area_m2===null||site.area_m2===undefined?'暂无数据 / 使用后端默认参数':`${number(site.area_m2)} m²`}}</strong></div><div><span>人口</span><strong>{{site.population===null||site.population===undefined?'暂无数据 / 使用后端默认参数':`${number(site.population)} 人`}}</strong></div><div><span>当前平均负荷</span><strong>{{loadStats?.average_load_kw===null||loadStats?.average_load_kw===undefined?'暂无数据 / 无法评估':`${number(loadStats.average_load_kw)} kW`}}</strong></div><div><span>辐照条件</span><strong>{{weatherStats?.peak_ghi_w_m2===null||weatherStats?.peak_ghi_w_m2===undefined?'暂无数据 / 使用后端默认参数':`峰值 ${number(weatherStats.peak_ghi_w_m2)} W/m²`}}</strong></div><div><span>平均风速</span><strong>{{averageWind===null?'暂无数据 / 无法评估':`${number(averageWind)} m/s`}}</strong></div></div></article>

<article class="panel recommendation-section"><div class="panel-head"><div><span>PROFILES & WEIGHTS</span><h2>推荐画像与评分权重</h2></div><el-switch v-model="advanced" active-text="高级自定义权重" inactive-text="使用后端默认画像权重"/></div><el-checkbox-group v-model="profiles" class="profile-select"><el-checkbox-button value="ECONOMIC">经济优先</el-checkbox-button><el-checkbox-button value="REDUCTION">减排优先</el-checkbox-button><el-checkbox-button value="BALANCED">综合平衡</el-checkbox-button></el-checkbox-group><div v-if="advanced" class="weights-grid"><div v-for="profile in profiles" :key="profile"><h3>{{profileLabels[profile]}} <small>当前总和 {{weightTotals[profile].toFixed(2)}}（后端自动归一化）</small></h3><label v-for="(label,key) in {reduction:'减排潜力',investment:'投资成本',payback:'回收期',applicability:'技术适用性',target:'目标满足度'}" :key="key">{{label}}<el-input-number v-model="weights[profile][key as keyof RecommendationWeights]" :min="0" :step=".05"/></label></div></div></article>

<article class="panel recommendation-section" data-testid="audited-measure-library"><div class="panel-head"><div><span>CANDIDATE LIBRARY · {{measureCatalog?.schema_version}}</span><h2>已审计候选措施</h2></div><label>实验参数级别 <el-select v-model="experimentScale" style="width:120px" @change="applyCatalog"><el-option label="LOW" value="LOW"/><el-option label="MEDIUM" value="MEDIUM"/><el-option label="HIGH" value="HIGH"/></el-select></label></div><div class="candidate-grid"><div v-for="c in candidates" :key="c.type" :class="{disabled:!c.enabled}"><header><b>{{catalogItem(c.type)?.measure_name||c.type}}</b><el-tag size="small">{{catalogItem(c.type)?.recommendation_status||'未审计'}}</el-tag><el-switch v-model="c.enabled" :disabled="catalogItem(c.type)?.recommendation_status==='BLOCKED_BY_ACCESS'"/></header><label>覆盖投资成本<el-input-number v-model="c.capex" :min="0" clearable/></label><label>{{experimentScale}} 参数（JSON）<el-input v-model="c.parameters" type="textarea" :rows="3" :disabled="!c.enabled"/></label><small>来源：{{Object.values(catalogItem(c.type)?.parameter_sources||{}).join(' / ')}}</small><small v-if="!c.enabled">当前证据不足，不进入后端候选组合</small></div></div></article>

<article class="panel recommendation-section generation-panel"><div><span>GENERATE</span><h2>生成推荐</h2><p>执行期间只展示真实 Loading，不伪造进度。</p></div><div v-if="formErrors.length" class="recommendation-errors"><span v-for="x in formErrors" :key="x">{{x}}</span></div><el-button type="primary" size="large" :loading="generating" :disabled="formErrors.length>0" @click="confirmVisible=true">生成 Top-{{topN}} 推荐</el-button><el-alert v-if="failure" :title="failure" type="error" :closable="false" show-icon/></article>

<template v-if="run"><section v-for="profile in profiles" :key="profile" class="recommendation-section"><div class="profile-heading"><div><span>{{profile}}</span><h2>{{profileLabels[profile]}}</h2></div><b>{{grouped[profile].length}} 条路径</b></div><div v-if="grouped[profile].length" class="path-grid"><article v-for="path in grouped[profile]" :key="path.id" class="path-card" :class="{selected:selectedPath?.id===path.id}" @click="selectedPath=path"><header><span>#{{path.rank}}</span><strong>{{path.score.toFixed(4)}}</strong><small>综合评分</small></header><div class="path-measures"><el-tag v-for="m in path.measures_json" :key="m.type">{{m.type}}</el-tag></div><dl><dt>措施数量</dt><dd>{{path.measures_json.length}}</dd><dt>预计减排</dt><dd>{{number(path.metrics_json.estimated_reduction_t)}} tCO₂</dd><dt>投资额</dt><dd>{{number(path.metrics_json.investment)}}</dd><dt>回收期</dt><dd>{{path.metrics_json.payback_years===null?'不可回收':`${number(path.metrics_json.payback_years)} 年`}}</dd><dt>技术适用性</dt><dd>{{percent(path.metrics_json.technical_applicability)}}</dd><dt>目标满足度</dt><dd>{{percent(path.metrics_json.target_satisfaction)}}</dd><dt>最大守恒误差</dt><dd>{{number(path.validation_summary_json.max_energy_balance_error_kwh)}} kWh</dd></dl><el-button link @click.stop="expanded.includes(path.id)?expanded=expanded.filter(x=>x!==path.id):expanded.push(path.id)">{{expanded.includes(path.id)?'收起详情':'展开详情'}}</el-button><div v-if="expanded.includes(path.id)" class="path-detail"><h4>后端推荐理由</h4><p v-for="reason in path.reasons_json" :key="reason">{{reason}}</p><h4>措施关键参数</h4><div v-for="m in path.measures_json" :key="m.type"><b>{{m.type}}</b><code>{{JSON.stringify(m.parameters)}}</code></div><h4>目标满足情况</h4><div class="target-status"><span v-for="item in [{k:'peak',n:'碳达峰目标'},{k:'neutral',n:'碳中和目标'},{k:'quota',n:'碳配额'},{k:'energy',n:'综合能耗目标'},{k:'budget',n:'预算'}]" :key="item.k">{{item.n}} <el-tag :type="statusType(status(path,item.k as 'peak'|'neutral'|'quota'|'energy'|'budget'))">{{status(path,item.k as 'peak'|'neutral'|'quota'|'energy'|'budget')}}</el-tag></span></div><h4>仿真验证</h4><p>{{path.validation_summary_json.validated?'已通过':'未通过'}} {{path.validation_summary_json.engine}} · {{path.validation_summary_json.hours??'—'}} 小时</p><p>碳排 {{number(path.metrics_json.carbon_emission_t)}} tCO₂ · 减排 {{number(path.metrics_json.estimated_reduction_t)}} tCO₂ · 购电 {{number(path.metrics_json.grid_power_kwh)}} kWh</p><el-alert v-if="(path.validation_summary_json.max_energy_balance_error_kwh??0)>1e-6" title="能源守恒误差异常" type="error" :closable="false"/><div class="path-actions"><el-button type="primary" @click.stop="openConvert(path)">转为正式场景</el-button><template v-if="converted[path.id]"><el-button @click.stop="router.push({path:'/scenarios',query:{scenario:converted[path.id].id}})">进入场景管理</el-button><el-button @click.stop="router.push({path:'/simulation',query:{scenario_version:converted[path.id].current_version_id}})">进入仿真推演</el-button></template><el-tooltip v-else content="需先转换为正式 ScenarioVersion"><el-button disabled>基于此方案继续仿真</el-button></el-tooltip></div></div></article></div><EmptyState v-else title="当前约束条件下暂无可行推荐路径" description="可调整预算或候选措施后重新生成"/></section>

<section class="recommendation-section chart-grid"><article class="panel"><h3>五维评分雷达</h3><BaseChart :option="radarOption" :empty="!selectedPath?.metrics_json.score_dimensions"/></article><article class="panel"><h3>Top-N 减排量</h3><BaseChart :option="reductionOption" :empty="!displayedPaths.length"/></article><article class="panel"><h3>Top-N 投资额</h3><BaseChart :option="investmentOption" :empty="!displayedPaths.length"/></article><article class="panel"><h3>Top-N 回收期</h3><BaseChart :option="paybackOption" :empty="!displayedPaths.length"/></article><article class="panel wide"><h3>减排量—投资额权衡</h3><BaseChart :option="scatterOption" :empty="!displayedPaths.length"/></article></section></template><EmptyState v-else title="当前尚无推荐结果" description="配置目标、画像和候选措施后生成真实推荐"/>
</main><aside><article class="panel history-panel"><div class="panel-head"><div><span>HISTORY</span><h2>历史推荐</h2></div></div><el-select v-model="historyId" placeholder="输入或选择 Run ID" filterable allow-create @change="loadHistory"><el-option v-for="h in history" :key="h.id" :label="`Run #${h.id} · ${new Date(h.created_at).toLocaleString('zh-CN')}`" :value="h.id"/></el-select><dl v-if="run"><dt>Run ID</dt><dd>#{{run.id}}</dd><dt>推荐年份</dt><dd>{{run.simulation_year}}</dd><dt>生成时间</dt><dd>{{new Date(run.created_at).toLocaleString('zh-CN')}}</dd><dt>基准碳排</dt><dd>{{number(run.baseline_summary_json.carbon_emission_t)}} tCO₂</dd><dt>基准购电</dt><dd>{{number(run.baseline_summary_json.grid_power_kwh)}} kWh</dd></dl></article></aside></div>
</template><EmptyState v-else title="暂无 Site" description="请先在数据中心创建 Site"/>
<el-dialog v-model="confirmVisible" title="推荐输入摘要" width="650px"><pre class="request-preview">{{JSON.stringify(requestPreview,null,2)}}</pre><p>候选参数和权重将提交后端，最终组合、评分和排序由 LowCarbonPathRecommendationEngine 完成。</p><template #footer><el-button @click="confirmVisible=false">取消</el-button><el-button type="primary" @click="generate">确认生成</el-button></template></el-dialog>
<el-dialog v-model="convertVisible" title="转为正式场景" width="600px"><el-form label-position="top"><el-form-item label="场景名称"><el-input v-model="convertForm.name"/></el-form-item><el-form-item label="描述"><el-input v-model="convertForm.description"/></el-form-item><div class="convert-years"><el-form-item label="基准年"><el-input-number v-model="convertForm.base_year"/></el-form-item><el-form-item label="开始年"><el-input-number v-model="convertForm.start_year"/></el-form-item><el-form-item label="结束年"><el-input-number v-model="convertForm.end_year"/></el-form-item></div></el-form><el-alert title="转换将复制推荐参数创建新的正式场景，不修改原推荐记录" type="info" :closable="false"/><template #footer><el-button @click="convertVisible=false">取消</el-button><el-button type="primary" @click="convert">确认转换</el-button></template></el-dialog>
</section></template>
